1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"context"
6		"database/sql"
7		"errors"
8		"fmt"
9		"strings"
10	
11		"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
12		_ "modernc.org/sqlite"
13	)
14	
15	// Store wraps the SQLite handle so callers never touch database/sql directly.
16	type Store struct {
17		db *sql.DB
18	}
19	
20	// Open prepares the database file and the schema this service needs.
21	func Open(path string) (*Store, error) {
22		return open(path, "sqlite")
23	}
24	
25	// open is Open with an injectable driver name, which lets the package tests
26	// register a driver wrapper around the real SQLite driver.
27	func open(path, driverName string) (*Store, error) {
28		dsn := path
29		if strings.Contains(dsn, "?") {
30			dsn += "&"
31		} else {
32			dsn += "?"
33		}
34		// foreign_keys must be enabled per connection; busy_timeout lets a
35		// concurrent writer wait for an open write transaction instead of
36		// failing immediately with SQLITE_BUSY.
37		dsn += "_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)"
38	
39		db, err := sql.Open(driverName, dsn)
40		if err != nil {
41			return nil, fmt.Errorf("open sqlite: %w", err)
42		}
43		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
44			db.Close()
45			return nil, fmt.Errorf("enable wal: %w", err)
46		}
47		if _, err := db.Exec(schema); err != nil {
48			db.Close()
49			return nil, fmt.Errorf("apply schema: %w", err)
50		}
51		return &Store{db: db}, nil
52	}
53	
54	// Ping reports whether the storage layer is usable.
55	func (s *Store) Ping() error { return s.db.Ping() }
56	
57	// Close releases the database handle.
58	func (s *Store) Close() error { return s.db.Close() }
59	
60	// queryer is satisfied by *sql.DB, *sql.Tx and *sql.Conn.
61	type queryer interface {
62		ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
63		QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
64		QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
65	}
66	
67	// preparer is the transaction surface a write callback gets: the loaders'
68	// queryer plus context-aware statement preparation for the batched detail
69	// inserts. *sql.Conn satisfies it.
70	type preparer interface {
71		queryer
72		PrepareContext(ctx context.Context, query string) (*sql.Stmt, error)
73	}
74	
75	// txMode selects how a managed transaction starts.
76	type txMode int
77	
78	const (
79		// txDeferred issues a plain BEGIN: a read transaction that pins one
80		// committed snapshot for every SELECT inside it.
81		txDeferred txMode = iota
82		// txImmediate issues BEGIN IMMEDIATE, taking the writer lock up front.
83		txImmediate
84	)
85	
86	// withTx is the single transaction lifecycle rule of the service; Register and
87	// List both run their work through it, so the lifecycle is verifiable from one
88	// place instead of being maintained twice:
89	//
90	//  1. acquire a dedicated connection and return it to the pool on every exit
91	//     (deferred Conn.Close);
92	//  2. begin the transaction in the requested mode;
93	//  3. run fn against that connection;
94	//  4. COMMIT exactly once when fn succeeds; otherwise — including an early
95	//     business return such as model.ErrConflict — best-effort ROLLBACK.
96	//
97	// The error fn returns is passed through untouched, so sentinel business
98	// errors stay errors.Is-recognizable and a storage error keeps its original
99	// cause. A failure of COMMIT itself is mapped to model.ErrStorageUnavailable;
100	// a failure of the best-effort ROLLBACK is deliberately swallowed so it can
101	// never replace the already-determined business or storage error.
102	func (s *Store) withTx(ctx context.Context, mode txMode, fn func(q preparer) error) error {
103		c, err := s.db.Conn(ctx)
104		if err != nil {
105			return unavailable(err)
106		}
107		// Rule 1: the connection is always returned, on success, business error
108		// and storage failure alike.
109		defer c.Close()
110	
111		begin := "BEGIN"
112		if mode == txImmediate {
113			// BEGIN IMMEDIATE takes the writer lock up front, so two concurrent
114			// registrations for the same artifact/version serialize and the loser
115			// re-reads the winner's committed row instead of hitting the unique
116			// constraint.
117			begin = "BEGIN IMMEDIATE"
118		}
119		if _, err := c.ExecContext(ctx, begin); err != nil {
120			return unavailable(err)
121		}
122	
123		committed := false
124		// Rule 4: any exit without a successful COMMIT rolls back. The cleanup is
125		// best effort and its error is discarded on purpose.
126		defer func() {
127			if !committed {
128				_, _ = c.ExecContext(context.Background(), "ROLLBACK")
129			}
130		}()
131	
132		if err := fn(c); err != nil {
133			return err
134		}
135		if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
136			return unavailable(err)
137		}
138		committed = true
139		return nil
140	}
141	
142	// Register persists a normalized SBOM in a single write transaction. When the
143	// same artifact and version already hold an identical manifest, the existing
144	// record (with its original ID) is returned and created is false. Different
145	// content leaves the existing record untouched and returns model.ErrConflict.
146	func (s *Store) Register(ctx context.Context, in *model.SBOM) (sbom *model.SBOM, created bool, err error) {
147		var result *model.SBOM
148		createdResult := false
149		txErr := s.withTx(ctx, txImmediate, func(q preparer) error {
150			var existingID int64
151			switch err := q.QueryRowContext(ctx,
152				"SELECT id FROM sboms WHERE artifact = ? AND version = ?",
153				in.Artifact, in.Version,
154			).Scan(&existingID); {
155			case err == nil:
156				existing, err := loadSBOM(ctx, q, existingID)
157				if err != nil {
158					return err
159				}
160				if !equalContent(existing, in) {
161					return model.ErrConflict
162				}
163				result = existing
164				return nil
165			case errors.Is(err, sql.ErrNoRows):
166				// Continue and insert.
167			default:
168				return unavailable(err)
169			}
170	
171			res, err := q.ExecContext(ctx,
172				"INSERT INTO sboms (artifact, version) VALUES (?, ?)",
173				in.Artifact, in.Version)
174			if err != nil {
175				return unavailable(err)
176			}
177			id, err := res.LastInsertId()
178			if err != nil {
179				return unavailable(err)
180			}
181	
182			componentID := make(map[string]int64, len(in.Components))
183			insertComponent, err := q.PrepareContext(ctx,
184				"INSERT INTO components (sbom_id, coordinate, license) VALUES (?, ?, ?)")
185			if err != nil {
186				return unavailable(err)
187			}
188			defer insertComponent.Close()
189			for i := range in.Components {
190				comp := &in.Components[i]
191				res, err := insertComponent.ExecContext(ctx, id, comp.Coordinate, comp.License)
192				if err != nil {
193					return unavailable(err)
194				}
195				compID, err := res.LastInsertId()
196				if err != nil {
197					return unavailable(err)
198				}
199				componentID[comp.Coordinate] = compID
200			}
201	
202			if depCount := countDependencies(in); depCount > 0 {
203				insertDep, err := q.PrepareContext(ctx,
204					"INSERT INTO dependencies (component_id, target_id) VALUES (?, ?)")
205				if err != nil {
206					return unavailable(err)
207				}
208				defer insertDep.Close()
209				for i := range in.Components {
210					comp := &in.Components[i]
211					for _, dep := range comp.Dependencies {
212						if _, err := insertDep.ExecContext(ctx, componentID[comp.Coordinate], componentID[dep]); err != nil {
213							return unavailable(err)
214						}
215					}
216				}
217			}
218	
219			out := *in
220			out.ID = id
221			result = &out
222			createdResult = true
223			return nil
224		})
225		if txErr != nil {
226			return nil, false, txErr
227		}
228		return result, createdResult, nil
229	}
230	
231	// List returns one page of complete SBOMs for an artifact ordered by ID, plus
232	// the total number of matching manifests. The count, the page manifests and
233	// the components/dependencies of that page are each read in one batched query
234	// (four SELECTs at most, regardless of page size) inside one transaction, so
235	// the total and the details share one committed snapshot and detail rows are
236	// never fetched for other pages or other artifacts. The detail reads go
237	// through the same loadComponentsInto/loadDependenciesInto loaders that
238	// Register's idempotency check uses, keeping one reconstruction rule.
239	func (s *Store) List(ctx context.Context, artifact string, page, pageSize int) (items []*model.SBOM, total int, err error) {
240		txErr := s.withTx(ctx, txDeferred, func(q preparer) error {
241			if err := q.QueryRowContext(ctx,
242				"SELECT COUNT(*) FROM sboms WHERE artifact = ?", artifact,
243			).Scan(&total); err != nil {
244				return unavailable(err)
245			}
246	
247			rows, err := q.QueryContext(ctx,
248				"SELECT id, artifact, version FROM sboms WHERE artifact = ? ORDER BY id ASC LIMIT ? OFFSET ?",
249				artifact, pageSize, (page-1)*pageSize)
250			if err != nil {
251				return unavailable(err)
252			}
253			defer rows.Close()
254	
255			items = []*model.SBOM{}
256			ids := make([]int64, 0, pageSize)
257			indexByID := make(map[int64]int, pageSize)
258			for rows.Next() {
259				sbom := &model.SBOM{Components: []model.Component{}}
260				if err := rows.Scan(&sbom.ID, &sbom.Artifact, &sbom.Version); err != nil {
261					return unavailable(err)
262				}
263				ids = append(ids, sbom.ID)
264				indexByID[sbom.ID] = len(items)
265				items = append(items, sbom)
266			}
267			if err := rows.Err(); err != nil {
268				return unavailable(err)
269			}
270	
271			// Empty page (unknown artifact or a page past the last one): the count
272			// was already read, and the two detail queries must not run with an
273			// empty IN list. Total is still returned to the caller.
274			if len(ids) == 0 {
275				return nil
276			}
277	
278			if err := loadComponentsInto(ctx, q, items, ids, indexByID); err != nil {
279				return err
280			}
281			if err := loadDependenciesInto(ctx, q, items, ids, indexByID); err != nil {
282				return err
283			}
284			return nil
285		})
286		if txErr != nil {
287			return nil, 0, txErr
288		}
289		return items, total, nil
290	}
291	
292	// Diff loads two registered manifests of one artifact for comparison. Both
293	// manifests are reconstructed inside one deferred read transaction and so
294	// share one committed snapshot: the caller can never compare two versions
295	// read from different commits, and neither manifest can ever be a
296	// half-written registration because Register commits the sbom row and every
297	// component/dependency atomically. When fromVersion and toVersion are
298	// identical the manifest is read once and the same record fills both result
299	// slots. A missing version yields model.ErrNotFound — still just that one
300	// error when both versions are absent. Every other read failure becomes
301	// model.ErrStorageUnavailable with no partial result.
302	func (s *Store) Diff(ctx context.Context, artifact, fromVersion, toVersion string) (from, to *model.SBOM, err error) {
303		var fromSBOM, toSBOM *model.SBOM
304		txErr := s.withTx(ctx, txDeferred, func(q preparer) error {
305			// The unique (artifact, version) constraint makes the IN-list return
306			// at most one row per version; collapse equal versions to one slot so
307			// a self-comparison reads its manifest only once.
308			versions := []string{fromVersion, toVersion}
309			if fromVersion == toVersion {
310				versions = []string{fromVersion}
311			}
312			query := `
313	SELECT id, artifact, version FROM sboms
314	WHERE artifact = ? AND version IN (` + placeholders(len(versions)) + `)
315	ORDER BY id ASC`
316			args := make([]any, 0, len(versions)+1)
317			args = append(args, artifact)
318			for _, version := range versions {
319				args = append(args, version)
320			}
321			rows, err := q.QueryContext(ctx, query, args...)
322			if err != nil {
323				return unavailable(err)
324			}
325			defer rows.Close()
326	
327			items := []*model.SBOM{}
328			ids := make([]int64, 0, len(versions))
329			indexByID := make(map[int64]int, len(versions))
330			byVersion := make(map[string]*model.SBOM, len(versions))
331			for rows.Next() {
332				sbom := &model.SBOM{Components: []model.Component{}}
333				if err := rows.Scan(&sbom.ID, &sbom.Artifact, &sbom.Version); err != nil {
334					return unavailable(err)
335				}
336				ids = append(ids, sbom.ID)
337				indexByID[sbom.ID] = len(items)
338				items = append(items, sbom)
339				byVersion[sbom.Version] = sbom
340			}
341			if err := rows.Err(); err != nil {
342				return unavailable(err)
343			}
344	
345			// Existence is settled against this snapshot before any detail read;
346			// a single not-found result is returned even when both versions miss.
347			fromSBOM = byVersion[fromVersion]
348			toSBOM = byVersion[toVersion]
349			if fromSBOM == nil || toSBOM == nil {
350				return model.ErrNotFound
351			}
352	
353			// One batched read per detail table for both manifests (or the single
354			// self-comparison manifest), through the same loaders List and
355			// Register use, so components and direct dependency edges follow the
356			// one reconstruction rule.
357			if err := loadComponentsInto(ctx, q, items, ids, indexByID); err != nil {
358				return err
359			}
360			if err := loadDependenciesInto(ctx, q, items, ids, indexByID); err != nil {
361				return err
362			}
363			return nil
364		})
365		if txErr != nil {
366			return nil, nil, txErr
367		}
368		return fromSBOM, toSBOM, nil
369	}
370	
371	// loadComponentsInto reads every component of the given manifests in one
372	// query and attaches the ordered components to their manifests. It is the
373	// single component reconstruction rule of the service: List calls it for the
374	// current page, and Register's idempotency/conflict check calls it (through
375	// loadSBOM) for the one stored manifest, so both read paths rebuild
376	// components exactly the same way.
377	func loadComponentsInto(ctx context.Context, q queryer, items []*model.SBOM, ids []int64, indexByID map[int64]int) error {
378		query := `
379	SELECT c.sbom_id, c.coordinate, c.license
380	FROM components c
381	WHERE c.sbom_id IN (` + placeholders(len(ids)) + `)
382	ORDER BY c.sbom_id ASC, c.coordinate ASC`
383		args := int64Args(ids)
384		rows, err := q.QueryContext(ctx, query, args...)
385		if err != nil {
386			return unavailable(err)
387		}
388		defer rows.Close()
389	
390		for rows.Next() {
391			var sbomID int64
392			var comp model.Component
393			comp.Dependencies = []string{}
394			if err := rows.Scan(&sbomID, &comp.Coordinate, &comp.License); err != nil {
395				return unavailable(err)
396			}
397			items[indexByID[sbomID]].Components = append(items[indexByID[sbomID]].Components, comp)
398		}
399		return rowsError(rows.Err())
400	}
401	
402	// loadDependenciesInto reads every dependency edge of the given manifests in
403	// one query. Both endpoints belong to the same manifest: the JOIN on sbom_id
404	// keeps edges scoped to the given manifests and also prevents a target row
405	// from another version ever matching when coordinates repeat across versions.
406	// Like loadComponentsInto it is shared by List (for a page) and by Register's
407	// idempotency/conflict check (through loadSBOM, for a single manifest).
408	func loadDependenciesInto(ctx context.Context, q queryer, items []*model.SBOM, ids []int64, indexByID map[int64]int) error {
409		query := `
410	SELECT sc.sbom_id, sc.coordinate, tc.coordinate
411	FROM dependencies d
412	JOIN components sc ON sc.id = d.component_id
413	JOIN components tc ON tc.id = d.target_id AND tc.sbom_id = sc.sbom_id
414	WHERE sc.sbom_id IN (` + placeholders(len(ids)) + `)
415	ORDER BY sc.sbom_id ASC, sc.coordinate ASC, tc.coordinate ASC`
416		rows, err := q.QueryContext(ctx, query, int64Args(ids)...)
417		if err != nil {
418			return unavailable(err)
419		}
420		defer rows.Close()
421	
422		// Coordinates are unique within a manifest, so a (sbom ID, coordinate) pair
423		// locates the owning component even when two versions share a coordinate.
424		coordinateIndex := make(map[int64]map[string]int, len(items))
425		for _, sbom := range items {
426			byCoordinate := make(map[string]int, len(sbom.Components))
427			for j := range sbom.Components {
428				byCoordinate[sbom.Components[j].Coordinate] = j
429			}
430			coordinateIndex[sbom.ID] = byCoordinate
431		}
432	
433		for rows.Next() {
434			var sbomID int64
435			var from, to string
436			if err := rows.Scan(&sbomID, &from, &to); err != nil {
437				return unavailable(err)
438			}
439			comp := &items[indexByID[sbomID]].Components[coordinateIndex[sbomID][from]]
440			comp.Dependencies = append(comp.Dependencies, to)
441		}
442		return rowsError(rows.Err())
443	}
444	
445	// rowsError maps a drained cursor's terminal error without wrapping nil.
446	func rowsError(err error) error {
447		if err == nil {
448			return nil
449		}
450		return unavailable(err)
451	}
452	
453	// placeholders builds "?,?,?" for an IN-list of n values.
454	func placeholders(n int) string {
455		return strings.Repeat("?,", n-1) + "?"
456	}
457	
458	func int64Args(ids []int64) []any {
459		args := make([]any, len(ids))
460		for i, id := range ids {
461			args[i] = id
462		}
463		return args
464	}
465	
466	// loadSBOM reconstructs a single stored manifest for Register's
467	// idempotency/conflict check. It reads the manifest row itself, then rebuilds
468	// components and dependencies through the same loaders List applies to a
469	// page, so the registration read path and the paged read path share one
470	// reconstruction rule by construction.
471	func loadSBOM(ctx context.Context, q queryer, id int64) (*model.SBOM, error) {
472		sbom := &model.SBOM{ID: id, Components: []model.Component{}}
473		if err := q.QueryRowContext(ctx,
474			"SELECT artifact, version FROM sboms WHERE id = ?", id,
475		).Scan(&sbom.Artifact, &sbom.Version); err != nil {
476			return nil, unavailable(err)
477		}
478	
479		// A one-manifest page: the shared loaders keep the component and
480		// dependency ordering/scoping rules identical to List's paged reads.
481		items := []*model.SBOM{sbom}
482		ids := []int64{id}
483		indexByID := map[int64]int{id: 0}
484		if err := loadComponentsInto(ctx, q, items, ids, indexByID); err != nil {
485			return nil, err
486		}
487		if err := loadDependenciesInto(ctx, q, items, ids, indexByID); err != nil {
488			return nil, err
489		}
490		return sbom, nil
491	}
492	
493	// equalContent compares normalized manifests (sorted components and
494	// dependencies); artifact and version already matched in SQL.
495	func equalContent(a, b *model.SBOM) bool {
496		if len(a.Components) != len(b.Components) {
497			return false
498		}
499		for i := range a.Components {
500			x, y := &a.Components[i], &b.Components[i]
501			if x.Coordinate != y.Coordinate || x.License != y.License {
502				return false
503			}
504			if len(x.Dependencies) != len(y.Dependencies) {
505				return false
506			}
507			for j := range x.Dependencies {
508				if x.Dependencies[j] != y.Dependencies[j] {
509					return false
510				}
511			}
512		}
513		return true
514	}
515	
516	func countDependencies(in *model.SBOM) int {
517		n := 0
518		for i := range in.Components {
519			n += len(in.Components[i].Dependencies)
520		}
521		return n
522	}
523	
524	func unavailable(err error) error {
525		if errors.Is(err, model.ErrStorageUnavailable) {
526			return err
527		}
528		return fmt.Errorf("%w: %v", model.ErrStorageUnavailable, err)
529	}
530	
531	const schema = `
532	CREATE TABLE IF NOT EXISTS service_metadata (
533	    key   TEXT PRIMARY KEY,
534	    value TEXT NOT NULL
535	);
536	CREATE TABLE IF NOT EXISTS sboms (
537	    id       INTEGER PRIMARY KEY,
538	    artifact TEXT NOT NULL,
539	    version  TEXT NOT NULL,
540	    UNIQUE (artifact, version)
541	);
542	CREATE TABLE IF NOT EXISTS components (
543	    id         INTEGER PRIMARY KEY,
544	    sbom_id    INTEGER NOT NULL REFERENCES sboms(id) ON DELETE CASCADE,
545	    coordinate TEXT NOT NULL,
546	    license    TEXT NOT NULL,
547	    UNIQUE (sbom_id, coordinate)
548	);
549	CREATE TABLE IF NOT EXISTS dependencies (
550	    id           INTEGER PRIMARY KEY,
551	    component_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
552	    target_id    INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
553	    UNIQUE (component_id, target_id)
554	);
555	CREATE INDEX IF NOT EXISTS idx_sboms_artifact ON sboms(artifact);
556	`
557

