143		postSBOM(t, router, `{"artifact":"app","version":"2","components":[
144			{"coordinate":"new-name","license":"MIT","dependencies":[]}
145		]}`)
146	
147		got := decodeDiff(t, getSBOMs(t, router, "/sboms/diff?artifact=app&fromVersion=1&toVersion=2"))
148		if len(got.Removed) != 1 || got.Removed[0].Coordinate != "old-name" {
149			t.Fatalf("removed = %+v", got.Removed)
150		}
151		if len(got.Added) != 1 || got.Added[0].Coordinate != "new-name" {
152			t.Fatalf("added = %+v", got.Added)
153		}
154		if len(got.Changed) != 0 {
