159	// TestDiffOnlyDirectRelationsAndNoPropagation: a license change on a
160	// dependency target and a transitive edge change deeper in the graph must not
161	// mark the referencing components as changed — only components whose own
162	// license or own direct dependency set changed appear.
163	func TestDiffOnlyDirectRelationsAndNoPropagation(t *testing.T) {
164		router, _ := newTestRouter(t)
165		postSBOM(t, router, `{"artifact":"app","version":"1","components":[
