171		// identical own license and own direct edges.
172		postSBOM(t, router, `{"artifact":"app","version":"2","components":[
173			{"coordinate":"a","license":"L","dependencies":["b"]},
174			{"coordinate":"b","license":"L","dependencies":["c"]},
175			{"coordinate":"c","license":"NEW","dependencies":["d"]},
