328	// TestDiffTrimsParamsAndMatchesCaseSensitively verifies normalization of the
329	// three identifiers and exact, case-sensitive matching.
330	func TestDiffTrimsParamsAndMatchesCaseSensitively(t *testing.T) {
331		router, _ := newTestRouter(t)
332		postSBOM(t, router, `{"artifact":"  App  ","version":" 1 ","components":[]}`)
333		postSBOM(t, router, `{"artifact":"App","version":"2","components":[]}`)
