344	
345		// Different casing on artifact matches nothing: 404. A padded value
346		// trims first, so " 9 " is looked up as the still-missing version "9".
347		expectError(t, getSBOMs(t, router, "/sboms/diff?artifact=app&fromVersion=1&toVersion=2"),
348			http.StatusNotFound, "SbomNotFoundError")
