353	// TestDiffStorageFailureReturns503WithoutPartialResult forces each read to
354	// fail and asserts the contracted error-only envelope with no internals.
355	func TestDiffStorageFailureReturns503WithoutPartialResult(t *testing.T) {
356		for _, kind := range []string{"sboms", "components", "dependencies"} {
357			t.Run(kind, func(t *testing.T) {
358				router, counted := newCountedRouter(t)
359				postSBOM(t, router, `{"artifact":"app","version":"1","components":[
360					{"coordinate":"a","license":"A","dependencies":["b"]},
361					{"coordinate":"b","license":"B","dependencies":[]}
362				]}`)
363				postSBOM(t, router, `{"artifact":"app","version":"2","components":[
364					{"coordinate":"a","license":"A2","dependencies":[]}
365				]}`)
366				counted.FailNextRead(kind)
367	
368				rec := getSBOMs(t, router, "/sboms/diff?artifact=app&fromVersion=1&toVersion=2")
369				if rec.Code != http.StatusServiceUnavailable {
370					t.Fatalf("%s failure: status = %d, want 503; body %s", kind, rec.Code, rec.Body.String())
371				}
372				assertErrorOnlyEnvelope(t, rec.Body.Bytes())
373				expectError(t, rec, http.StatusServiceUnavailable, "storage_unavailable")
374				for _, leaked := range []string{"SELECT", "SQLITE", "sql:", "goroutine", ".go:", "forced read failure"} {
375					if bytes.Contains(rec.Body.Bytes(), []byte(leaked)) {
376						t.Fatalf("response leaks %q: %s", leaked, rec.Body.String())
377					}
378				}
379			})
380		}
381	}
