415	// TestBuildDiffComparesDependenciesAsSets unit-tests the order-independence
416	// of the direct dependency comparison: stored reconstructions are always
417	// sorted, but the rule must hold regardless of array order.
418	func TestBuildDiffComparesDependenciesAsSets(t *testing.T) {
419		before := &model.SBOM{Artifact: "app", Version: "1", Components: []model.Component{
420			{Coordinate: "a", License: "L", Dependencies: []string{"x", "y", "z"}},
421		}}
